// 이미지 로드 실패 시 몇 차례 재시도 후에만 대체 이미지로 전환(또는 제거).
// 새로고침 직후 등 순간적인 네트워크/캐시 문제로 실패한 경우, 그대로 포기하지 않고
// 캐시를 우회하는 쿼리스트링을 붙여 다시 요청해본다.
// index.html, clear-share.html 공용.
function handleImgError(img, fallbackSrc) {
    const attempts = parseInt(img.dataset.retryCount || '0', 10);
    const maxRetries = 2;
    if (attempts < maxRetries) {
        img.dataset.retryCount = String(attempts + 1);
        const originalSrc = img.dataset.originalSrc || img.src.split('?')[0];
        img.dataset.originalSrc = originalSrc;
        setTimeout(() => { img.src = originalSrc + '?retry=' + Date.now(); }, 300 * (attempts + 1));
    } else if (fallbackSrc) {
        img.onerror = null;
        img.src = fallbackSrc;
    } else {
        img.remove();
    }
}

// 보유 유닛 수량(counts: {code: count, ...})만으로 지속 적용 버프/디버프 합계를 계산.
// 확률/조건부 발동 스킬 문구는 제외하고, 순수하게 항상 적용되는 스탯 라인만 집계한다.
// index.html(computeBuffTotals)과 clear-share.html이 공용으로 사용한다.
function computeUnitStatTotals(counts) {
    const totals = { armor: 0, slow: 0, atk: 0, atkFlat: 0, atkSpeed: 0, hpRegen: 0, manaRegen: 0, ampMagic: 0, ampExplosive: 0, ampAll: 0, magicArmor: 0 };
    const EXCLUDE = /확률|공격시|기본\s*공격에|발동|조건|적중시|스킬|매\s|소모|지속시간|쿨타임/;

    for (const [code, count] of Object.entries(counts)) {
        if (!count || count <= 0) continue;
        const unit = unitDB.find(u => u.code === code);
        if (!unit || !unit.stats) continue;

        const flags = {};
        unit.stats.forEach(stat => {
            if (stat === 'ㅡㅡㅡ' || stat.startsWith('▶') || stat.startsWith('◎')) return;
            if (EXCLUDE.test(stat)) return;

            let m;
            const sForArmor = stat.replace(/마법\s*방어력\s*감소|마법방어력\s*감소|마방깎/g, "");
            if (!flags.armor && (m = sForArmor.match(/방어력\s*감소\s*[-]?\s*(\d+(?:\.\d+)?)/))) { totals.armor += parseFloat(m[1]); flags.armor = true; }
            else if (!flags.armor && (m = sForArmor.match(/방어력\s*증가\s*[-]?\s*(\d+(?:\.\d+)?)/))) { totals.armor -= parseFloat(m[1]); flags.armor = true; }

            if (!flags.slow && (m = stat.match(/이동속도\s*감소\s*[-]?\s*(\d+(?:\.\d+)?)/) || stat.match(/이속\s*감소\s*[-]?\s*(\d+(?:\.\d+)?)/))) { totals.slow += parseFloat(m[1]); flags.slow = true; }

            if (!flags.atk && (m = stat.match(/공격력\s*증가\s*(\d+(?:\.\d+)?)%/))) { totals.atk += parseFloat(m[1]); flags.atk = true; }

            if (!flags.atkSpeed && (m = stat.match(/공격속도\s*증가\s*(\d+(?:\.\d+)?)%/))) { totals.atkSpeed += parseFloat(m[1]); flags.atkSpeed = true; }

            if (!flags.hpRegen && !flags.manaRegen && (m = stat.match(/체력\s*및\s*마나\s*재생\s*(\d+(?:\.\d+)?)/))) {
                totals.hpRegen += parseFloat(m[1]); totals.manaRegen += parseFloat(m[1]); flags.hpRegen = true; flags.manaRegen = true;
            } else {
                if (!flags.hpRegen && (m = stat.match(/체력\s*재생\s*(\d+(?:\.\d+)?)/))) { totals.hpRegen += parseFloat(m[1]); flags.hpRegen = true; }
                if (!flags.manaRegen && (m = stat.match(/마나\s*재생\s*(\d+(?:\.\d+)?)/))) { totals.manaRegen += parseFloat(m[1]); flags.manaRegen = true; }
            }

            if (!flags.magicArmor && (m = stat.match(/마법\s*방어력\s*감소\s*(\d+(?:\.\d+)?)%/))) { totals.magicArmor += parseFloat(m[1]); flags.magicArmor = true; }

            if (!flags.ampMagic && (m = stat.match(/마법\s*데미지\s*(\d+(?:\.\d+)?)%\s*증폭/))) { totals.ampMagic += parseFloat(m[1]); flags.ampMagic = true; }
            if (!flags.ampExplosive && (m = stat.match(/폭발형\s*데미지\s*(\d+(?:\.\d+)?)%\s*증폭/))) { totals.ampExplosive += parseFloat(m[1]); flags.ampExplosive = true; }
            if (!flags.ampAll && (m = stat.match(/모든\s*피해량\s*(\d+(?:\.\d+)?)%\s*증폭/))) { totals.ampAll += parseFloat(m[1]); flags.ampAll = true; }
        });
    }

    return totals;
}

// 조합에 들어간 "전설 환산 개수" 계산 (clear-share.html 전용).
// 전설 등급 유닛 자체 = 1. 전설보다 상위 등급(히든~세라핌 등)은 재귀적으로 하위 재료를 따라가며 합산.
// 전설보다 하위 등급(희귀/특별 등)은 인접 등급 간 3:1 비율을 가정해 (1/3)^(전설과의 등급 차이)로 환산.
// 예) 희귀 3개 = 전설 1개 → 희귀 1개 = 약 0.33, 불멸 1개(전설 3개 필요) = 전설 3개.
function legendaryEquivalentOf(code, multiplier) {
    const unit = unitDB.find(u => u.code === code);
    if (!unit) return 0;

    const order = gradeOrder[unit.grade];
    const legendOrder = gradeOrder['legendary'];
    if (order === legendOrder) return multiplier;

    if (order > legendOrder) {
        if (!unit.req) return 0;
        let sum = 0;
        for (const [reqCode, reqCount] of Object.entries(unit.req)) {
            sum += legendaryEquivalentOf(reqCode, multiplier * reqCount);
        }
        return sum;
    }

    const distance = legendOrder - order;
    return multiplier * Math.pow(1 / 3, distance);
}

function computeLegendaryCount(counts) {
    let total = 0;
    for (const [code, count] of Object.entries(counts || {})) {
        if (!count || count <= 0) continue;
        total += legendaryEquivalentOf(code, count);
    }
    return Math.round(total * 10) / 10;
}

